      SUBROUTINE FITTINCC     READS IN ALL DATA, UNSCRAMBLES, AND FITS INTO DATA ARRAYCC     LIST OF COMMON BLOCKSC      INCLUDE 'DATA2A.CIN'      INCLUDE 'DATA2D.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'IMAGE.CIN'      INCLUDE 'IOFLAG.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'LIMITS.CIN'      INCLUDE 'RDBUFF.CIN'      INCLUDE 'RDCARD.CIN'      INCLUDE 'RDCHAR.CIN'      INCLUDE 'RDCOMS.CIN'      INCLUDE 'RDPRNT.CIN'CC     LOCAL VARIABLESC      LOGICAL  FLAG      INTEGER  J, LCC----------------------------------------------------------------------C     READ AND PRINT TITLE AND INDICATORC      LIST = .TRUE.      RFM = .FALSE.      BEF = .TRUE.      PRNT = .TRUE.      SLV = .TRUE.      BWT = .FALSE.      BRD = .FALSE.      NPSTEP = NPSTEP + 1C      ECHO = .FALSE.      CALL TITLE      IF (ENDFIL) GO TO 600C    2 NORAYS = 0      CALL RDIND(FLAG)      IF (ENDFIL) GO TO 600      IF (LIST) THEN        WRITE (NOUT,9001)        WRITE (NOUT,9000) IMAGE        IF (NCOMS .GT. 0) THEN          L = LCOM          WRITE (NOUT,1004) (CMMNT(J), J = 1, L), PARENC 1004     FORMAT (1H0,11X,'(',79A1)        ENDIF        WRITE (NOUT,9005) KTEXT      ENDIF      IF (NPSTEP .EQ. 1 .AND. INDIC .NE. 0) FLAG = .TRUE.      IF (FLAG) THEN        WRITE (NOUT, 9010)        INDIC = 0        INDS = 0      ENDIF      IF (INDS .NE. 0) GO TO 200CC     READ NEW SYSTEMC  100 ECHO = LIST .AND. .NOT. RFM      NUSE = 0      CALL RDDATA      IF (ENDFIL) THEN        CALL RDENDF        GO TO 600      ENDIF      GO TO 400CC     CONVERT INTERNAL VARY CODES TO EXTERNALC  200 ECHO = LIST .AND. .NOT. RFM      CALL RDVCEX      IF (ENDFIL) GO TO 600  400 IF (LIST .AND. RFM) WRITE (NOUT,9400)CC     CONVERT EXTERNAL VARY CODES TO INTERNALC  500 IF (FLUSHL) WRITE (NOUT,9150)      IF (FLUSHL .OR. LIST) WRITE (NOUT,9160) NEL, NELLIM, I, IDLIMC  600 RETURNC 9000 FORMAT (1H0,10X,1H",A80,1H") 9001 FORMAT (1H1) 9005 FORMAT (1H0,10X,A80) 9010 FORMAT ('0INDICATOR VALUE WRONG OR MISSING - ZERO ASSUMED') 9150 FORMAT ('0DATA OVERFLOW OR ERRORS, RUN FLUSHED') 9160 FORMAT (1H0,I5,' ELEMENTS USED OUT OF A MAXIMUM ALLOWABLE',I5/     1        1H ,I5,' NUMBERS USED OUT OF A MAXIMUM ALLOWABLE',I6) 9400 FORMAT (9H0SENTINEL)      END